def transform(grid):
    g=[r[:] for r in grid]
    # Extend each upper endpoint toward the corresponding bottom marker,
    # preserving the marker row itself (demo shows row 14 is last painted).
    for c,color in ((5,2),(9,4),(14,6)):
        for r in range(len(g)-2):
            g[r][c]=color
    return g
PY

