def transform(grid):
    g=[r[:] for r in grid]
    h,w=len(g),len(g[0])
    for c in [j for j in range(w) if g[h-1][j]==5]:
        seeds=[(r,g[r][c]) for r in range(h) if g[r][c]!=0]
        for r in range(h):
            _,color=min(seeds,key=lambda p:(abs(p[0]-r),-p[0]))
            g[r][c]=color
    return g
